-- Cycle identity fixes the revision; actual SQL measurements own their timestamps.
-- The collector retains the first page instance/sourceAt baseline across pages,
-- while subsequent tenant observations and page observedAt remain actual.
create or replace function public.m15_03_observe_instance(p_instance_id uuid,p_observed_at timestamptz,p_after_id uuid default null,p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=pg_catalog,public set statement_timeout='500ms' as $$
declare tenants jsonb;next_id uuid;inst jsonb;metadata jsonb;t timestamptz:=statement_timestamp();rev bigint;sources jsonb;heartbeat timestamptz;critical boolean;feed_at timestamptz;feed_status text;begin
 if p_instance_id is null or p_observed_at is null or not isfinite(p_observed_at) or p_observed_at>t+interval '5 seconds' or p_observed_at<t-interval '5 minutes' or p_limit is null or p_limit not between 1 and 100 then raise exception 'invalid local observation' using errcode='22023';end if;
 rev:=floor(extract(epoch from p_observed_at)*1000)::bigint;
 select last_evaluated_at,critical_at is not null into heartbeat,critical from public.reporting_deadline_monitor_health where singleton;
 select min(coalesce(last_source_snapshot_at,last_success_at)),case when bool_or(not enabled or coalesce(last_source_snapshot_at,last_success_at) is null) then 'unknown' when bool_or(coalesce(last_source_snapshot_at,last_success_at)<t-make_interval(secs=>stale_threshold_seconds)) then 'stale' when count(*)>0 then 'healthy' else 'unknown' end into feed_at,feed_status from public.vulnerability_feed_configs;
 sources:=jsonb_build_array(
 jsonb_build_object('source','database','status','healthy','sourceAt',public.m7_snapshot_timestamp_utc(t),'observedAt',public.m7_snapshot_timestamp_utc(t),'attemptedAt',public.m7_snapshot_timestamp_utc(t),'succeededAt',public.m7_snapshot_timestamp_utc(t),'receivedAt',public.m7_snapshot_timestamp_utc(t),'reasons','[]'::jsonb),
 jsonb_build_object('source','deadline_monitor','status',case when heartbeat is null then 'unknown' when critical then 'degraded' when heartbeat<t-interval '120 seconds' then 'stale' else 'healthy' end,'sourceAt',public.m7_snapshot_timestamp_utc(heartbeat),'observedAt',public.m7_snapshot_timestamp_utc(t),'attemptedAt',public.m7_snapshot_timestamp_utc(t),'succeededAt',public.m7_snapshot_timestamp_utc(t),'receivedAt',public.m7_snapshot_timestamp_utc(t),'reasons',case when heartbeat is null then array['worker_heartbeat_unavailable'] when heartbeat<t-interval '120 seconds' then array['worker_heartbeat_stale'] when critical then array['source_unavailable'] else '{}'::text[] end),
 jsonb_build_object('source','vulnerability_feeds','status',feed_status,'sourceAt',public.m7_snapshot_timestamp_utc(feed_at),'observedAt',public.m7_snapshot_timestamp_utc(t),'attemptedAt',public.m7_snapshot_timestamp_utc(t),'succeededAt',public.m7_snapshot_timestamp_utc(t),'receivedAt',public.m7_snapshot_timestamp_utc(t),'reasons',case feed_status when 'unknown' then array['no_successful_observation'] when 'stale' then array['source_stale'] else '{}'::text[] end),
 jsonb_build_object('source','backups','status','unknown','sourceAt',null,'observedAt',public.m7_snapshot_timestamp_utc(t),'attemptedAt',null,'succeededAt',null,'receivedAt',null,'reasons',array['m15_05_not_available'])
 );
 inst:=jsonb_build_object('instanceId',p_instance_id,'label','CRA instance','status',case when feed_status='stale' or (heartbeat is not null and heartbeat<t-interval '120 seconds') then 'stale' when critical then 'degraded' else 'unknown' end,'version',null,'commit',null,'expectedVersion',null,'versionDrift','unknown','versionSourceAt',null,'lastObservedAt',public.m7_snapshot_timestamp_utc(t),'licenceSummary',jsonb_build_object('active',null,'grace',null,'expiredReadOnly',null,'invalid',null,'missing',null,'unknown',null),'tenantCount',null,'countScope','authorized_tenants','sources',sources);
 with page as(select o.id,o.name,o.updated_at,m.updated_at meter_at,m.storage_ready and m.protected_storage_ready meter_ready from public.organizations o left join public.organization_usage_meters m on m.organization_id=o.id where o.is_active and (p_after_id is null or o.id>p_after_id) order by o.id limit p_limit+1)
 select coalesce(jsonb_agg(jsonb_build_object('tenantId',id,'label',name,'status','unknown','licenceState',null,'licenceExpiresAt',null,'graceEndsAt',null,'licenceSourceAt',null,'lastObservedAt',public.m7_snapshot_timestamp_utc(updated_at),'sources',jsonb_build_array(jsonb_build_object('source','usage_metering','status',case when meter_ready then 'healthy' else 'unknown' end,'sourceAt',public.m7_snapshot_timestamp_utc(meter_at),'observedAt',public.m7_snapshot_timestamp_utc(t),'attemptedAt',public.m7_snapshot_timestamp_utc(t),'succeededAt',public.m7_snapshot_timestamp_utc(t),'receivedAt',public.m7_snapshot_timestamp_utc(t),'reasons',case when meter_ready then '{}'::text[] else array['meter_unavailable'] end))) order by id)filter(where rn<=p_limit),'[]'::jsonb),max(id::text)filter(where rn=p_limit)::uuid into tenants,next_id from(select page.*,row_number()over(order by id)rn from page)p;
 if jsonb_array_length(tenants)<p_limit or not exists(select 1 from public.organizations where is_active and id>next_id) then next_id:=null;end if;
 metadata:=jsonb_build_object('schemaVersion',1,'instanceId',p_instance_id,'revision',rev,'sourceAt',public.m7_snapshot_timestamp_utc(t),'observedAt',public.m7_snapshot_timestamp_utc(t),'instance',inst,'tenants',tenants,'nextCursor',replace(next_id::text,'-',''));
 return metadata;end $$;
notify pgrst,'reload schema';
